fn spec() -> Value {
    serde_json::from_str(SPEC).expect("authored Select fixture")
}
fn cases() -> Vec<Value> {
    spec()["cases"].as_array().expect("forty cases").clone()
}
fn text(case: &Value, key: &str) -> String {
    case[key].as_str().unwrap_or_default().to_string()
}
fn optional(case: &Value, key: &str) -> Option<String> {
    case[key].as_str().map(str::to_string)
}
fn selections(value: &Value) -> Vec<String> {
    match value {
        Value::Array(rows) => rows
            .iter()
            .filter_map(Value::as_str)
            .map(str::to_string)
            .collect(),
        Value::String(value) if !value.is_empty() => vec![value.clone()],
        _ => Vec::new(),
    }
}
fn options() -> Vec<SelectOption> {
    spec()["options"]
        .as_array()
        .expect("options")
        .iter()
        .map(|row| {
            let option = SelectOption::new(text(row, "value"), text(row, "label"));
            if row["disabled"] == true {
                option.disabled()
            } else {
                option
            }
        })
        .collect()
}
fn state(name: &str) -> FieldState {
    match name {
        "invalid" => FieldState::Invalid,
        "valid" => FieldState::Valid,
        "info" => FieldState::Info,
        "warning" => FieldState::Warning,
        _ => FieldState::Default,
    }
}
fn sentinel_style(scope: usize, revision: usize) -> String {
    let config = spec();
    let mut style = String::new();
    for (index, token) in config["colorTokens"]
        .as_array()
        .expect("tokens")
        .iter()
        .enumerate()
    {
        style.push_str(&format!(
            "--{}:rgb({},{},{});",
            token.as_str().unwrap_or_default(),
            24 + (13 * index + 7 * scope + 3 * revision) % 160,
            32 + (11 * index + 5 * scope + 7 * revision) % 150,
            40 + (7 * index + 3 * scope + 11 * revision) % 140
        ));
    }
    for (token, base) in config["sizeTokens"].as_object().expect("sizes") {
        let size = base.as_i64().unwrap_or_default() + scope as i64 + revision as i64
            - if ["size-60", "size-70", "size-80", "size-90"].contains(&token.as_str()) {
                4 * (scope as i64 % 2)
            } else {
                0
            };
        style.push_str(&format!("--si-sys-sizing-{token}:{size}px;"));
    }
    let size = 14 + scope + revision;
    let line = 20 + scope + revision;
    let paragraph_size = 15 + scope + revision;
    let paragraph_line = 23 + scope + revision;
    let tracking = 0.25 + 0.25 * revision as f64;
    let timing = if revision == 0 { "0s" } else { ".001s" };
    style.push_str(&format!("font:400 16px/24px system-ui,sans-serif;color:var(--si-sys-color-text-primary);--si-sys-typography-body:400 {size}px/{line}px system-ui,sans-serif;--si-sys-typography-body-paragraph:400 {paragraph_size}px/{paragraph_line}px system-ui,sans-serif;--si-sys-typography-body-sbold:600 {size}px/{line}px system-ui,sans-serif;--si-ref-typography-letter-spacing-normal:{tracking}px;--si-sys-color-effects-shadow-4:0 4px 12px rgb(0 0 0 / .24);--theme-default-time:{timing};--theme-medium-time:{timing};--theme-z-index-dropdown:20;--focus--border-color:var(--si-sys-color-effects-focus);"));
    style
}
fn override_style(revision: usize) -> String {
    let mut style = String::from("#select-visual-review .select-component-override{");
    for (name, value) in spec()["overrides"].as_object().expect("overrides") {
        let value = if let Some(number) = value.as_i64() {
            format!("{}px", number + revision as i64)
        } else {
            value.as_str().unwrap_or_default().to_string()
        };
        style.push_str(&format!("{name}:{value};"));
    }
    style.push('}');
    style
}
#[derive(Clone, Copy, PartialEq)]
struct Consumer {
    value: Signal<String>,
    requests: Signal<Vec<Value>>,
    commands: Signal<usize>,
}
impl Consumer {
    fn snapshot(self) -> String {
        json!({"value":(self.value)(),"requests":(self.requests)()}).to_string()
    }
    fn accept(mut self, value: String) {
        let before = (self.value)();
        self.value.set(value.clone());
        let mut requests = self.requests.write();
        let sequence = requests.len() + 1;
        requests.push(json!({"sequence":sequence,"before":before,"value":value}));
    }
    fn command(mut self, value: &str, reset: bool) {
        self.value.set(value.into());
        if reset {
            self.requests.set(Vec::new());
        }
        self.commands += 1;
    }
}
